/**
 * =============================================================================
 * KS-1457 — audit.ts reads req.path three more times inside res.on('finish')
 * =============================================================================
 * KS-871 captured the path once at entry (`auditPath`) because a responding `router.use` gate leaves `req.path`
 * mount-relative, and 'finish' fires before anything restores it. It fixed the row's `details.path`. Three other
 * reads inside the same 'finish' callback still used the trimmed `req.path`:
 *
 *   A  the login special case that lifts the user id out of a 200 login response (`user_id` and `resource_id`),
 *   B  the attempted-login email (`details.attemptedEmail`) taken from the request body,
 *   C  the `path` in the "audit middleware: write failed" warning.
 *
 * Each cell mounts a responding gate UNDER the login path, so that at 'finish' `req.path` is '/', and asserts the
 * canonical `/api/auth/login` behaviour. The unmounted controls (a plain `app.post`) leave `req.path` whole and
 * already pass on base: they are what the gate's behaviour is measured against. B4 uses the REAL gate production
 * has: the login rate limiter (`express-rate-limit`, mounted at `/api/auth/login` after the audit middleware in
 * index.ts and answering 429 itself), so the trimmed read is live in production today, not only for a future gate.
 * Whether the audit's entry gates
 * should fold case (`/API/auth/login` is not audited) is KS-1191's design question and is NOT touched here.
 * =============================================================================
 */
import { describe, it, expect, afterEach, vi, type Mock } from 'vitest';
import express from 'express';
import http from 'node:http';
import type { AddressInfo } from 'node:net';
import rateLimit from 'express-rate-limit';
import { createAuditMiddleware } from '../middleware/audit';

const USER_ID = '3caac0a0-0bf8-415b-aa31-aec9636e7ef5';
const EXPECTED_CELLS = 8;
let CELLS_RUN = 0;

type QueryMock = Mock<(sql: string, params: unknown[]) => Promise<{ rows: unknown[] }>>;
type LogMock = Mock<(level: string, msg: string, ctx?: Record<string, unknown>) => void>;
const makeQuery = (): QueryMock => vi.fn(async (_sql: string, _params: unknown[]) => ({ rows: [] as unknown[] }));
const makeLog = (): LogMock => vi.fn((_l: string, _m: string, _c?: Record<string, unknown>) => undefined);

const servers: http.Server[] = [];
afterEach(async () => { while (servers.length) { const s = servers.pop()!; s.closeAllConnections(); await new Promise<void>((r) => s.close(() => r())); } });

/**
 * `mounted: true` answers from a gate mounted UNDER the path (req.path is '/' at 'finish');
 * `mounted: false` answers from a plain route on the full path (req.path stays whole).
 */
async function drive(opts: { mounted: boolean; path: string; status: number; reply: object; body: object; query: QueryMock; log: LogMock }): Promise<void> {
  const app = express();
  app.use(express.json());
  app.use(createAuditMiddleware({ query: opts.query, isDbAvailable: () => true, log: opts.log }));
  const handler: express.RequestHandler = (_req, res) => { res.status(opts.status).json(opts.reply); };
  if (opts.mounted) app.use(opts.path, handler); else app.post(opts.path, handler);
  const server = app.listen(0, '127.0.0.1');
  servers.push(server);
  await new Promise<void>((r) => server.once('listening', () => r()));
  const port = (server.address() as AddressInfo).port;
  await new Promise<void>((resolve, reject) => {
    const req = http.request({ host: '127.0.0.1', port, path: opts.path, method: 'POST', headers: { 'content-type': 'application/json' } },
      (res) => { res.resume(); res.on('end', () => resolve()); });
    req.on('error', reject);
    req.end(JSON.stringify(opts.body));
  });
}

async function until(cond: () => boolean, what: string, timeout = 2500): Promise<void> {
  const start = Date.now();
  while (Date.now() - start < timeout) { if (cond()) return; await new Promise((r) => setTimeout(r, 25)); }
  throw new Error(`${what} never happened within ${timeout} ms`);
}

const LOGIN_OK = { data: { user: { id: USER_ID } } };

describe('KS-1457 A — the login response lifts the user id into the audit row, mounted or not', () => {
  it('RED KS-1457 A1 — a 200 login answered from a gate mounted under /api/auth/login records user_id and resource_id', async () => {
    CELLS_RUN += 1;
    const query = makeQuery();
    await drive({ mounted: true, path: '/api/auth/login', status: 200, reply: LOGIN_OK, body: { email: 'a@ks1457.test' }, query, log: makeLog() });
    await until(() => query.mock.calls.length > 0, 'the audit write');
    const p = query.mock.calls[0][1] as unknown[];
    expect([p[1], p[5]], 'user_id and resource_id come from the response, as for an unmounted route').toEqual([USER_ID, USER_ID]);
  });

  it('GREEN control KS-1457 A2 — the same 200 login from a plain route on the full path records them (the behaviour A1 must match)', async () => {
    CELLS_RUN += 1;
    const query = makeQuery();
    await drive({ mounted: false, path: '/api/auth/login', status: 200, reply: LOGIN_OK, body: { email: 'a@ks1457.test' }, query, log: makeLog() });
    await until(() => query.mock.calls.length > 0, 'the audit write');
    const p = query.mock.calls[0][1] as unknown[];
    expect([p[1], p[5]]).toEqual([USER_ID, USER_ID]);
  });
});

describe('KS-1457 B — the attempted-login email is recorded, mounted or not', () => {
  const BODY = { email: 'Who@Example.COM' };
  it('RED KS-1457 B1 — a refused (429) login from a mounted gate records details.attemptedEmail, lower-cased', async () => {
    CELLS_RUN += 1;
    const query = makeQuery();
    await drive({ mounted: true, path: '/api/auth/login', status: 429, reply: { error: 'slow down' }, body: BODY, query, log: makeLog() });
    await until(() => query.mock.calls.length > 0, 'the audit write');
    const details = JSON.parse((query.mock.calls[0][1] as unknown[])[8] as string);
    expect(details.attemptedEmail).toBe('who@example.com');
    expect(details.path, 'KS-871 still holds: the row carries the full path').toBe('/api/auth/login');
  });

  it('GREEN control KS-1457 B2 — the same refusal from a plain route records it (the behaviour B1 must match)', async () => {
    CELLS_RUN += 1;
    const query = makeQuery();
    await drive({ mounted: false, path: '/api/auth/login', status: 429, reply: { error: 'slow down' }, body: BODY, query, log: makeLog() });
    await until(() => query.mock.calls.length > 0, 'the audit write');
    expect(JSON.parse((query.mock.calls[0][1] as unknown[])[8] as string).attemptedEmail).toBe('who@example.com');
  });

  it('GREEN control KS-1457 B3 — the email is taken ONLY for the login path: a mounted /api/auth/register gate with the same body records no attemptedEmail', async () => {
    CELLS_RUN += 1;
    const query = makeQuery();
    await drive({ mounted: true, path: '/api/auth/register', status: 400, reply: { error: 'bad' }, body: BODY, query, log: makeLog() });
    await until(() => query.mock.calls.length > 0, 'the audit write');
    const details = JSON.parse((query.mock.calls[0][1] as unknown[])[8] as string);
    expect(details.attemptedEmail, 'an exact-path match on the login route, not a loose one').toBeUndefined();
  });
});

describe('KS-1457 B4 — the production login limiter is exactly such a gate', () => {
  it('RED KS-1457 B4 — a throttled login (the real express-rate-limit at /api/auth/login, as in index.ts) is audited WITH its attemptedEmail, as the allowed one before it was', async () => {
    CELLS_RUN += 1;
    const query = makeQuery();
    const app = express();
    app.use(express.json());
    app.use(createAuditMiddleware({ query, isDbAvailable: () => true, log: makeLog() }));
    app.use('/api/auth/login', rateLimit({
      windowMs: 60 * 1000, max: 1, standardHeaders: true, legacyHeaders: false,
      message: { success: false, error: { code: 'RATE_LIMIT_EXCEEDED', message: 'Too many login attempts. Please try again later.' } },
    }));
    app.post('/api/auth/login', (_req, res) => { res.status(401).json({ error: 'bad credentials' }); });
    const server = app.listen(0, '127.0.0.1');
    servers.push(server);
    await new Promise<void>((r) => server.once('listening', () => r()));
    const port = (server.address() as AddressInfo).port;
    const statuses: number[] = [];
    for (const email of ['First@Example.com', 'Second@Example.com']) {
      await new Promise<void>((resolve, reject) => {
        const req = http.request({ host: '127.0.0.1', port, path: '/api/auth/login', method: 'POST', headers: { 'content-type': 'application/json' } },
          (res) => { statuses.push(res.statusCode ?? 0); res.resume(); res.on('end', () => resolve()); });
        req.on('error', reject);
        req.end(JSON.stringify({ email }));
      });
    }
    expect(statuses, 'the first attempt reaches the handler (401), the second is throttled by the real limiter (429)').toEqual([401, 429]);
    await until(() => query.mock.calls.length >= 2, 'both audit writes');
    const emails = query.mock.calls.map((c) => JSON.parse((c[1] as unknown[])[8] as string).attemptedEmail);
    expect(emails, 'both rows carry the attempted email; the throttled one is the one an operator most needs').toEqual(['first@example.com', 'second@example.com']);
  });
});

describe('KS-1457 C — the "write failed" warning carries the full path', () => {
  const failing = (): QueryMock => vi.fn(async (_sql: string, _params: unknown[]) => { throw new Error('ks1457 boom'); });
  const failedCtx = (log: LogMock) => log.mock.calls.find((c) => c[1] === 'audit middleware: write failed')?.[2];

  it('RED KS-1457 C1 — when the audit INSERT fails behind a mounted gate, the warning names /api/auth/login, not "/"', async () => {
    CELLS_RUN += 1;
    const log = makeLog();
    await drive({ mounted: true, path: '/api/auth/login', status: 401, reply: { error: 'no' }, body: { email: 'c@ks1457.test' }, query: failing(), log });
    await until(() => failedCtx(log) !== undefined, 'the write-failed warning');
    expect(failedCtx(log)).toMatchObject({ error: 'ks1457 boom', path: '/api/auth/login' });
  });

  it('GREEN control KS-1457 C2 — the same failure from a plain route already names the full path (the behaviour C1 must match)', async () => {
    CELLS_RUN += 1;
    const log = makeLog();
    await drive({ mounted: false, path: '/api/auth/login', status: 401, reply: { error: 'no' }, body: { email: 'c@ks1457.test' }, query: failing(), log });
    await until(() => failedCtx(log) !== undefined, 'the write-failed warning');
    expect(failedCtx(log)).toMatchObject({ path: '/api/auth/login' });
  });
});

describe('KS-1457 completeness', () => {
  it('KS-1457 COMPLETENESS — every graded cell above actually ran', () => {
    expect(CELLS_RUN).toBe(EXPECTED_CELLS);
  });
});
